const reviews = $input.all();

const reviewText = reviews.map((item) => {
  const r = item.json;

  return `
Review ID: ${r.review_id}
Date: ${r.review_date}
Rating: ${r.rating}
Review: ${r.review_text}
Source: ${r.source}
Product: ${r.product}
`;
}).join('\n---\n');

return [
  {
    json: {
      reviews_text: reviewText,
      total_reviews: reviews.length
    }
  }
];

